#!/usr/bin/env python3
"""Remove executable JavaScript from an HTML file, without reformatting it."""

import html
import re
import sys
from html.parser import HTMLParser


URI_ATTRIBUTES = {
    "href", "src", "action", "formaction", "cite", "poster", "background",
    "lowsrc", "dynsrc", "longdesc", "usemap", "profile", "archive",
    "classid", "codebase", "data", "xlink:href", "xml:base",
}


def dangerous_url(value):
    # HTML character references have already been decoded by HTMLParser, but
    # decode once more for unusual input passed through a parser unchanged.
    value = html.unescape(value or "")
    # Browsers ignore ASCII whitespace and controls when interpreting schemes.
    compact = re.sub(r"[\x00-\x20\x7f-\x9f]", "", value).lower()
    if compact.startswith(("javascript:", "vbscript:")):
        return True
    # SVG, HTML, and script data URLs are executable.  Removing data URLs from
    # URL attributes altogether also avoids browser-specific SVG image bugs.
    return compact.startswith("data:")


def dangerous_css(value):
    value = html.unescape(value or "").lower()
    if re.search(r"expression\s*\(|-moz-binding\s*:|behavior\s*:", value):
        return True
    for match in re.finditer(r"url\s*\(\s*(['\"]?)(.*?)\1\s*\)", value, re.I | re.S):
        if dangerous_url(match.group(2)):
            return True
    return False


def remove_attributes(raw, names):
    """Remove named attributes from a start tag while retaining its spelling."""
    if not names:
        return raw
    # Find the end of the tag name.  raw is the exact text supplied by the
    # parser, so this leaves all unrelated bytes (including whitespace) alone.
    i = 1
    while i < len(raw) and not raw[i].isspace() and raw[i] not in ">/":
        i += 1
    out = [raw[:i]]
    n = len(raw)
    while i < n:
        ws = i
        while i < n and raw[i].isspace():
            i += 1
        if i >= n or raw[i] in ">/":
            out.append(raw[ws:])
            break
        name_start = i
        while i < n and not raw[i].isspace() and raw[i] not in "=>":
            i += 1
        attr_name = raw[name_start:i].lower()
        while i < n and raw[i].isspace():
            i += 1
        if i < n and raw[i] == "=":
            i += 1
            while i < n and raw[i].isspace():
                i += 1
            if i < n and raw[i] in "\"'":
                quote = raw[i]
                i += 1
                while i < n and raw[i] != quote:
                    i += 1
                if i < n:
                    i += 1
            else:
                while i < n and not raw[i].isspace() and raw[i] != ">":
                    i += 1
        if attr_name not in names:
            out.append(raw[ws:i])
    return "".join(out)


class Filter(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.output = []
        self.in_script = False
        self.style_parts = None

    def emit(self, text):
        if not self.in_script and self.style_parts is None:
            self.output.append(text)
        elif self.style_parts is not None:
            self.style_parts.append(text)

    def handle_starttag(self, tag, attrs):
        tag_lower = tag.lower()
        raw = self.get_starttag_text()
        if tag_lower == "script":
            self.in_script = True
            return
        if tag_lower == "style":
            self.style_parts = [raw]
            return

        remove = set()
        http_equiv_refresh = False
        for name, value in attrs:
            lname = name.lower()
            if lname.startswith("on") or lname in {"srcdoc", "content-script-type"}:
                remove.add(lname)
            elif lname in URI_ATTRIBUTES and dangerous_url(value):
                remove.add(lname)
            elif lname == "style" and dangerous_css(value):
                remove.add(lname)
            elif tag_lower == "meta" and lname == "http-equiv" and (value or "").lower() == "refresh":
                http_equiv_refresh = True
        if http_equiv_refresh:
            for name, value in attrs:
                if name.lower() == "content" and dangerous_url((value or "").split(";", 1)[-1]):
                    remove.add("content")
        self.emit(remove_attributes(raw, remove))

    def handle_startendtag(self, tag, attrs):
        if tag.lower() in ("script", "style"):
            return
        # HTMLParser does not call handle_starttag for this form.
        raw = self.get_starttag_text()
        remove = set()
        for name, value in attrs:
            lname = name.lower()
            if lname.startswith("on") or lname == "srcdoc" or (lname in URI_ATTRIBUTES and dangerous_url(value)):
                remove.add(lname)
            elif lname == "style" and dangerous_css(value):
                remove.add(lname)
        self.output.append(remove_attributes(raw, remove))

    def handle_endtag(self, tag):
        tag_lower = tag.lower()
        if tag_lower == "script":
            self.in_script = False
        elif tag_lower == "style" and self.style_parts is not None:
            parts = self.style_parts
            self.style_parts = None
            css = "".join(parts[1:])
            if not dangerous_css(css):
                self.output.extend(parts)
                self.output.append(f"</{tag}>")
        elif not self.in_script and self.style_parts is None:
            self.output.append(f"</{tag}>")

    def handle_data(self, data):
        if self.in_script:
            return
        self.emit(data)

    def handle_comment(self, data):
        self.emit("<!--" + data + "-->")

    def handle_entityref(self, name):
        self.emit("&" + name + ";")

    def handle_charref(self, name):
        self.emit("&#" + name + ";")

    def handle_decl(self, decl):
        self.emit("<!" + decl + ">")

    def unknown_decl(self, data):
        self.emit("<![" + data + "]>")

    def handle_pi(self, data):
        self.emit("<?" + data + ">")


def main():
    if len(sys.argv) < 2:
        raise SystemExit(f"usage: {sys.argv[0]} FILE")
    path = sys.argv[1]
    with open(path, "rb") as f:
        source = f.read().decode("utf-8", "surrogateescape")
    parser = Filter()
    parser.feed(source)
    parser.close()
    with open(path, "wb") as f:
        f.write("".join(parser.output).encode("utf-8", "surrogateescape"))


if __name__ == "__main__":
    main()
